Rules.InvariantScript:
Clear(colWfDraftPhases);
Clear(colWfDraftWorkers);
Clear(colWfRows);
Clear(colWfRowsTmp);
Clear(colWfKeepPhases);
Clear(colWfKeepWorkers);
Set(_cmpWfExpanded, 0);
Set(_cmpWfDirty, false);
Set(_cmpWfReqTitle, "");
Set(_cmpWfSeedKey, "");
Set(_cmpWfNextId, 300000);
Set(_cmpAwOpen, false);
Set(_cmpPhOpen, false)

Clear(colWfDraftPhases);
Clear(colWfDraftWorkers);
Set(
    _cmpWfReqTitle,
    If(
        IsBlank(cmpDetEditWorkflow.RequestKey),
        "",
        LookUp(colRequests, RequestKey = cmpDetEditWorkflow.RequestKey).Title
    )
);
Collect(
    colWfDraftPhases,
    ForAll(
    Sort(Filter(colPhases, RequestKey = cmpDetEditWorkflow.RequestKey), PhaseOrder) As p,
        {
            ClientId: 1000 + p.PhaseOrder,
            PhaseKey: p.PhaseKey,
            Title: p.Title,
            PhaseOrder: p.PhaseOrder,
            PhaseGoal: p.PhaseGoal,
            PhaseStatusKey: p.PhaseStatusKey,
            IsLocked: p.PhaseStatusKey = "Completed",
            IsNew: false,
            IsRemoved: false
        }
    )
);
Collect(
    colWfDraftWorkers,
    ForAll(
    Filter(colAssignments, RequestKey = cmpDetEditWorkflow.RequestKey) As a,
        {
            ClientId: 100000 + a.ID,
            // DERIVED FROM THE ASSIGNMENT KEY, WHICH IS UNIQUE. This was
            // 100000 + 1000 * PhaseOrder + AssignmentOrder, and that COLLIDES
            // for parallel workers: two people in the same phase at the same
            // AssignmentOrder is how this app expresses "these run together",
            // and they came out with an identical ClientId.
            //
            // ClientId is what the edit dialog looks a row up by, so a
            // collision meant editing one parallel worker PATCHED THE OTHER.
            // When the other already held that value the draft did not change
            // at all, the save reported success, and the edit vanished with
            // nothing anywhere saying so.
            //
            // AssignmentKey is REQ-YYYY-NNNNNN-A<id> where id is the SharePoint
            // item id, so the tail after the last "-A" is unique per assignment
            // and small. The 100000 offset keeps it clear of the phase range
            // (1000+) and below _cmpWfNextId (300000+), so the three ranges
            // still cannot overlap.
            PhaseClientId: LookUp(colWfDraftPhases, PhaseKey = a.PhaseKey).ClientId,
            AssignmentKey: a.AssignmentKey,
            AssignmentOrder: a.AssignmentOrder,
            AssigneeName: a.AssigneeName,
            AssigneeEmail: a.AssigneeEmail,
            DepartmentCode: a.DepartmentCode,
            Goal: a.Goal,
            Required: a.Required,
            DurationDays: a.DurationDays,
            IsGroup: a.IsGroup,
            GroupId: a.GroupId,
            StatusKey: a.StatusKey,
            IsNew: false,
            IsRemoved: false
        }
    )
);
Set(_cmpWfNextId, 300000);
Set(_cmpWfDirty, false);
Set(_cmpWfExpanded, Coalesce(First(Filter(colWfDraftPhases, !IsLocked)).ClientId, 0));
Select(btnWfRebuild)
// A COMPONENT HAS NO OnVisible, so the host calls this when it opens the
// dialog. Everything after this point works on the draft and never
// touches the RequestPhases or RequestAssignments lists again.
//
// The request title is CAPTURED ONCE into _cmpWfReqTitle. It used to be a
// live LookUp on the Requests list inside the subtitle label, which meant
// a delegated call on every render of the header.
//
// IsLocked is DERIVED from PhaseStatusKey rather than stored. A
// Completed phase is read only because Flow has already recorded work
// against it, and deriving it means the rule cannot be edited into an
// inconsistent state by anything in this dialog.
//
// ClientId is a LOCAL join key and is never persisted. The ranges are now
// DISJOINT BY COLLECTION AND BY ORIGIN, which the old scheme was not:
//   phases   loaded 1000+order      template 2000+order
//   workers  loaded 100000+...      template 200000+...
//   anything created in this session 300000+ from _cmpWfNextId
// The old worker base of 1000 + 1000*order overlapped the template phase
// range at 2000, which was harmless only by accident.

Set(_cmpWfSeedKey, cmpDetEditWorkflow.SeedTemplateKey);
Select(btnWfLoadTemplate)
// THE SECOND ENTRY POINT INTO btnWfLoadTemplate. The header combo box is
// the first. Both set _cmpWfSeedKey and select the same button, so there is
// exactly one copy of the loader body.
//
// CALL ORDER MATTERS: LoadDraft first, then this. LoadDraft clears the draft
// and resets _cmpWfNextId, _cmpWfDirty and the expanded phase, so calling it
// after this would wipe the template that had just been appended.

If(
    !IsBlank(
        LookUp(colTemplates, TemplateKey = _cmpWfSeedKey).DefinitionJson
    ),
    ClearCollect(colWfKeepPhases, Filter(colWfDraftPhases, IsLocked, !IsRemoved));
    ClearCollect(
        colWfKeepWorkers,
        Filter(
            colWfDraftWorkers,
            !IsRemoved,
            PhaseClientId in colWfKeepPhases.ClientId
        )
    );
    Clear(colWfDraftPhases);
    Clear(colWfDraftWorkers);
    Collect(colWfDraftPhases, colWfKeepPhases);
    Collect(colWfDraftWorkers, colWfKeepWorkers);
    Set(_cmpWfBase, CountRows(colWfKeepPhases));
    ForAll(
        ParseJSON(
        LookUp(colTemplates, TemplateKey = _cmpWfSeedKey).DefinitionJson
    ).phases As ph,
        Collect(
            colWfDraftPhases,
            {
                ClientId: 2000 + Value(ph.order),
                PhaseKey: "",
                Title: Text(ph.name),
                PhaseOrder: _cmpWfBase + Value(ph.order),
                PhaseGoal: Text(ph.goal),
                PhaseStatusKey: "NotStarted",
                IsLocked: false,
                IsNew: true,
                IsRemoved: false
            }
        );
        Collect(
            colWfDraftWorkers,
            ForAll(
            Sequence(CountRows(Table(ph.assignments))) As ai,
                {
                    ClientId: 200000 + Value(ph.order) * 1000 + ai.Value,
                    PhaseClientId: 2000 + Value(ph.order),
                    AssignmentKey: "",
                    AssignmentOrder: Value(Index(ph.assignments, ai.Value).order),
                    AssigneeName: Text(Index(ph.assignments, ai.Value).role),
                    AssigneeEmail: "",
                    DepartmentCode: Text(Index(ph.assignments, ai.Value).deptCode),
                    Goal: Text(Index(ph.assignments, ai.Value).goal),
                    Required: Boolean(Index(ph.assignments, ai.Value).required),
                    DurationDays: Value(Index(ph.assignments, ai.Value).durationDays),
                    IsGroup: Boolean(Index(ph.assignments, ai.Value).isGroup),
                    GroupId: "",
                    StatusKey: "NotStarted",
                    IsNew: true,
                    IsRemoved: false
                }
            )
        )
    );
    Set(_cmpWfDirty, true);
    Set(_cmpWfNextId, 300000);
    Set(_cmpWfExpanded, Coalesce(First(Filter(colWfDraftPhases, !IsLocked)).ClientId, 0));
    Select(btnWfRebuild)
)
// ONE COPY OF THE LOADER, REACHED TWO WAYS. The template combo box in
// the dialog header selects a template and calls this; a host seeding a
// brand new request from a category calls the LoadTemplate action, which
// sets the same variable and selects the same button. The body lives here
// so the two entry points cannot drift apart.
//
// KEYED ON _cmpWfSeedKey, NOT ON THE COMBO BOX SELECTION, because the
// action route has no selection to read. The combo box writes the
// variable before selecting this.
//
// BLANK OR UNKNOWN KEY IS A NO OP, so an existing request can call
// LoadTemplate unconditionally right after LoadDraft without knowing
// whether it has a template.
//
// Completed phases SURVIVE a template load. Replacing a finished
// phase would discard work Flow has already recorded. The template
// appends after whatever is locked.
//
// Every ParseJSON read is explicitly cast. A missing field returns
// Blank() with no error, so an uncast read fails silently. JSON
// field names are case sensitive.
//
// CLIENTID IS KEYED ON POSITION, NOT ON a.order. PARALLEL WORKERS SHARE
// AN ORDER: two assignments in one phase at the same order is how this app
// expresses "these run together", and the shipped data does exactly that,
// Finance Reviewer and Technical Reviewer both at order 1.
//
// 200000 + phase * 1000 + Value(a.order) therefore produced an IDENTICAL
// ClientId for both rows. ClientId is what the edit dialog looks a row up
// by, so editing one parallel worker PATCHED THE OTHER, and where the
// other already held that value nothing changed at all and the edit
// vanished with no error. UnresolvedCount could then never reach zero, so
// Save stayed disabled permanently.
//
// THIS IS THE SAME DEFECT LoadDraft ALREADY FIXED for loaded rows, left
// behind on the template path. It only became reachable once the loader
// gained a second entry point and started running for every new request.
//
// Sequence over the assignment COUNT gives a per-phase position that is
// unique by construction; Index reads the untyped element positionally.
//
// Assignees arrive UNRESOLVED: role holds a role or group name and
// the payload has no email. The footer counts them and Save stays
// disabled until each is picked.
//
// THIS IS DESTRUCTIVE for unlocked work and there is no confirm
// step. See the notes shipped with this file if you want one.

ClearCollect(
    colWfRowsTmp,
    ForAll(
        Filter(colWfDraftPhases, !IsRemoved) As p,
        {
            RowType: "phase",
            SortPhase: p.PhaseOrder,
            SortRow: 0,
            PhaseClientId: p.ClientId,
            RowClientId: p.ClientId,
            Title: p.Title,
            Subtitle: p.PhaseGoal,
            StatusKey: p.PhaseStatusKey,
            StatusTitle: LookUp(nfStatusTable, StatusKey = p.PhaseStatusKey).Title,
            IsLocked: p.IsLocked,
            IsExpanded: p.ClientId = _cmpWfExpanded,
            WorkerCount: CountRows(Filter(colWfDraftWorkers, PhaseClientId = p.ClientId, !IsRemoved)),
            PhaseDays: Coalesce(
                Sum(
                    ForAll(
                        Distinct(
                            Filter(colWfDraftWorkers, PhaseClientId = p.ClientId, !IsRemoved),
                            AssignmentOrder
                        ) As d,
                        Max(
                            Filter(
                                colWfDraftWorkers,
                                PhaseClientId = p.ClientId,
                                !IsRemoved,
                                AssignmentOrder = d.Value
                            ),
                            DurationDays
                        )
                    ),
                    Value
                ),
                0
            ),
            AssignmentOrder: 0,
            DepartmentCode: "",
            Required: false,
            DurationDays: 0,
            IsGroup: false,
            AssigneeEmail: "",
            GroupId: ""
        }
    )
);
If(
    _cmpWfExpanded > 0,
    Collect(
        colWfRowsTmp,
        ForAll(
            Sort(Filter(colWfDraftWorkers, PhaseClientId = _cmpWfExpanded, !IsRemoved), AssignmentOrder) As w,
            {
                RowType: "worker",
                SortPhase: LookUp(colWfDraftPhases, ClientId = _cmpWfExpanded).PhaseOrder,
                SortRow: w.AssignmentOrder,
                PhaseClientId: w.PhaseClientId,
                RowClientId: w.ClientId,
                Title: w.AssigneeName,
                Subtitle: w.Goal,
                StatusKey: w.StatusKey,
                StatusTitle: LookUp(nfStatusTable, StatusKey = w.StatusKey).Title,
                IsLocked: LookUp(colWfDraftPhases, ClientId = _cmpWfExpanded).IsLocked,
                IsExpanded: false,
                WorkerCount: 0,
                PhaseDays: 0,
                AssignmentOrder: w.AssignmentOrder,
                DepartmentCode: w.DepartmentCode,
                Required: w.Required,
                DurationDays: w.DurationDays,
                IsGroup: w.IsGroup,
                AssigneeEmail: w.AssigneeEmail,
                GroupId: w.GroupId
            }
        )
    );
    If(
        !LookUp(colWfDraftPhases, ClientId = _cmpWfExpanded).IsLocked,
        Collect(
            colWfRowsTmp,
            {
                RowType: "add",
                SortPhase: LookUp(colWfDraftPhases, ClientId = _cmpWfExpanded).PhaseOrder,
                SortRow: 9999,
                PhaseClientId: _cmpWfExpanded,
                RowClientId: 0,
                Title: "",
                Subtitle: "",
                StatusKey: "",
                StatusTitle: "",
                IsLocked: false,
                IsExpanded: false,
                WorkerCount: 0,
                PhaseDays: 0,
                AssignmentOrder: 0,
                DepartmentCode: "",
                Required: false,
                DurationDays: 0,
                IsGroup: false,
                AssigneeEmail: "",
                GroupId: ""
            }
        )
    )
);
ClearCollect(
    colWfRows,
    SortByColumns(colWfRowsTmp, "SortPhase", SortOrder.Ascending, "SortRow", SortOrder.Ascending)
)
// HIDDEN REBUILD, called at the end of every draft mutation. It is a
// control rather than a behaviour UDF because it reads _cmpWfExpanded,
// and it is wrapped by the Rebuild action so the host can call it too.
//
// The two step collect through colWfRowsTmp is required: a ClearCollect
// whose source reads the collection it is clearing has undefined
// behaviour.
//
// PhaseDays and StatusTitle are now PROJECTED HERE ONCE. The duration
// aggregate used to be copy pasted into three places (the chip, the
// phase row and the footer) and re-evaluated on every render of each.
// StatusTitle removes a per render LookUp against nfStatusTable from every
// pill and tooltip.
//
// DURATION IS THE SUM OF THE LONGEST WORKER AT EACH ORDER, not the sum
// of every worker. Workers sharing an order run in parallel, so three
// three-day workers at order 1 cost three days, not nine.
//
// All three record shapes carry the SAME COLUMN SET. A Collect whose
// records disagree on columns silently widens the collection schema.
//
// A locked phase DOES contribute worker rows, so a Completed phase can
// still be opened and read. What it does not contribute is the dashed
// add row, and IsLocked rides along on every worker row so the edit,
// delete and stepper controls disable themselves from the data rather
// than from a dozen separate Visible formulas.

ForAll(
    colTemplates As t,
    {
        TemplateKey: t.TemplateKey,
        DefinitionJson: t.DefinitionJson,
        Label:
            t.Title
            & "  ("
            & CountRows(Table(ParseJSON(t.DefinitionJson).phases))
            & " phases)"
    }
)
// The phase count is DERIVED from the payload, never typed in,
// so the label and the data cannot disagree.

If(
    !IsBlank(Self.Selected.TemplateKey),
    Set(_cmpWfSeedKey, Self.Selected.TemplateKey);
    Select(btnWfLoadTemplate)
)
// A DISPATCHER, NOT THE LOADER. The body moved to
// btnWfLoadTemplate so the LoadTemplate action can reach it
// too. The explanation lives there with the code.

Max(
    150,
    (Parent.Width - 2 * nfSpace.Lg - 112 - nfSpace.Sm)
    / Max(1, CountRows(Filter(colWfRows, RowType = "phase")))
    - 2 * nfSpace.Sm
)
// CHIPS FIT INSTEAD OF SCROLLING while they can. Below about five
// phases the strip has no horizontal scroll at all, so nothing gets
// clipped mid chip. 112 is btnWfAddPhase.Width, which sits outside
// the gallery and has to come off the available width first.
//
// Parent.Width, NOT Self.Width. This gallery is FillPortions sized,
// and .Width on a FillPortions control returns 0.
//
// Past the floor of 150 the strip scrolls again, which is what
// Default is for: selecting the expanded phase pulls its chip into
// view, so the chip you are working on is never the clipped one.

Collect(
    colWfDraftPhases,
    {
        ClientId: _cmpWfNextId,
        PhaseKey: "",
        Title: "New Phase",
        PhaseOrder: CountRows(Filter(colWfDraftPhases, !IsRemoved)) + 1,
        PhaseGoal: "",
        PhaseStatusKey: "NotStarted",
        IsLocked: false,
        IsNew: true,
        IsRemoved: false
    }
);
Set(_cmpWfExpanded, _cmpWfNextId);
Set(_cmpWfNextId, _cmpWfNextId + 1);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)

Max(
    72,
    Parent.Width
        - 84
        - If(
              Parent.Width >= 660, 444,
              Parent.Width >= 580, 336,
              212
          )
)
// The three reserved widths track the right hand cluster as
// pieces of it drop out: status plus meta plus four buttons,
// then meta plus four buttons, then four buttons alone.

Coalesce(
    ThisItem.StatusTitle,
    LookUp(nfStatusTable, StatusKey = ThisItem.StatusKey).Title,
    "Not Started"
)
// THREE WAY FALLBACK, and the order matters. The rebuild
// projection is read first because it costs nothing. If it is
// blank, either nfStatusTable had not loaded when the rebuild ran
// or the collection schema is stale, so the live lookup runs.
// A frozen blank pill can never heal on its own, which is
// exactly what snapshotting this alone caused.

Set(_cmpWfExpanded, ThisItem.PhaseClientId);
Set(_cmpAwEditId, 0);
Set(_cmpAwPhaseClientId, ThisItem.PhaseClientId);
Set(_cmpAwIsGroup, false);
Set(_cmpAwName, "");
Set(_cmpAwId, "");
Set(_cmpAwGoal, "");
Set(_cmpAwDept, "OPS");
Set(
    _cmpAwOrder,
    Last(
        Sort(
            Filter(colWfDraftWorkers, PhaseClientId = ThisItem.PhaseClientId, !IsRemoved),
            AssignmentOrder
        )
    ).AssignmentOrder + 1
);
Set(_cmpAwDays, 3);
Set(_cmpAwRequired, true);
Set(_cmpAwOpen, true);
Reset(cmbAwPerson);
Select(btnWfRebuild)
// ADD A WORKER TO ANY PHASE THAT IS NOT COMPLETED, without
// having to expand it first. The dashed add row only ever
// belongs to the expanded phase, which made this the one
// action you could not reach from a collapsed row.
//
// The phase is EXPANDED FIRST so that when the dialog confirms
// and rebuilds, the worker you just created is on screen rather
// than hidden inside a collapsed phase.
//
// NEXT ORDER IS THE LAST WORKER'S ORDER PLUS ONE.
//
// PARALLEL WORKERS SHARE AN ORDER, so a COUNT is not a position:
// three people at order 1 is ONE step containing three people, and
// the next step is 2. Counting gave 4 and invented two empty steps.
//
// Last of an ASCENDING sort, which is the highest order present.
// Two earlier attempts used aggregates instead, Max(table, column)
// and a WorkerMaxOrder column projected by the rebuild, and the
// projected one came back blank and defaulted every worker to 1.
// This reads the draft directly and has no aggregate and no
// projected column to go stale.
//
// Blank + 1 is 1, so an empty phase puts its first worker on 1
// with no guard needed.
//
// DUPLICATED IN THE OTHER ADD HANDLER AND MUST STAY IDENTICAL. It
// cannot be shared: a named formula cannot see inside a component,
// a UDF signature is scalars only so the phase cannot be passed,
// and an internal _ output would have to read _cmpAwPhaseClientId,
// which this same handler is still writing. Two copies kept
// textually identical beats a clever shape that breaks.

Set(_cmpPhClientId, ThisItem.PhaseClientId);
Set(_cmpPhTitle, ThisItem.Title);
Set(_cmpPhGoal, ThisItem.Subtitle);
Set(_cmpPhOpen, true)

Patch(
    colWfDraftPhases,
    LookUp(
        colWfDraftPhases,
        !IsRemoved && PhaseOrder = ThisItem.SortPhase - 1
    ),
    { PhaseOrder: ThisItem.SortPhase }
);
Patch(
    colWfDraftPhases,
    LookUp(colWfDraftPhases, ClientId = ThisItem.PhaseClientId),
    { PhaseOrder: ThisItem.SortPhase - 1 }
);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)
// TWO PATCHES, AND THE ORDER MATTERS. The neighbour moves onto
// my order FIRST, so for one statement two rows share it. The
// second Patch then finds ME by ClientId, which is unique and
// unaffected, rather than by the now ambiguous PhaseOrder.
//
// ThisItem reads colWfRows, which is not rebuilt until the
// Select below, so ThisItem.SortPhase is a stable snapshot
// throughout.

If(
    ThisItem.IsLocked
        || ThisItem.SortPhase >= CountRows(Filter(colWfDraftPhases, !IsRemoved))
        || LookUp(
               colWfDraftPhases,
               !IsRemoved && PhaseOrder = ThisItem.SortPhase + 1
           ).IsLocked,
    DisplayMode.Disabled,
    DisplayMode.Edit
)
// MIRRORS THE UP GUARD. The old version checked only the end of
// the list, so a locked phase sitting below an unlocked one
// could be dragged upward by moving its neighbour down.

Patch(
    colWfDraftPhases,
    LookUp(
        colWfDraftPhases,
        !IsRemoved && PhaseOrder = ThisItem.SortPhase + 1
    ),
    { PhaseOrder: ThisItem.SortPhase }
);
Patch(
    colWfDraftPhases,
    LookUp(colWfDraftPhases, ClientId = ThisItem.PhaseClientId),
    { PhaseOrder: ThisItem.SortPhase + 1 }
);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)

Patch(
    colWfDraftPhases,
    LookUp(colWfDraftPhases, ClientId = ThisItem.PhaseClientId),
    { IsRemoved: true }
);
ForAll(
    Filter(colWfDraftWorkers, PhaseClientId = ThisItem.PhaseClientId) As w,
    Patch(colWfDraftWorkers, w, { IsRemoved: true })
);
ForAll(
    Sort(Filter(colWfDraftPhases, !IsRemoved), PhaseOrder) As p,
    Patch(
        colWfDraftPhases,
        p,
        {
            PhaseOrder: CountRows(
                Filter(colWfDraftPhases, !IsRemoved, PhaseOrder <= p.PhaseOrder)
            )
        }
    )
);
Set(_cmpWfDirty, true);
Set(
    _cmpWfExpanded,
    Coalesce(First(Filter(colWfDraftPhases, !IsRemoved, !IsLocked)).ClientId, 0)
);
Select(btnWfRebuild)
// Deleting a phase CASCADES to its workers and PhaseOrder is
// renumbered contiguously so the receiver never sees gaps. Both
// are soft: IsRemoved rows survive so Save can say what to
// delete.

Coalesce(
    ThisItem.StatusTitle,
    LookUp(nfStatusTable, StatusKey = ThisItem.StatusKey).Title,
    "Not Started"
)
// THREE WAY FALLBACK, and the order matters. The rebuild
// projection is read first because it costs nothing. If it is
// blank, either nfStatusTable had not loaded when the rebuild ran
// or the collection schema is stale, so the live lookup runs.
// A frozen blank pill can never heal on its own, which is
// exactly what snapshotting this alone caused.

If(ThisItem.Required, "Required. ", "Not required. ")
& If(
    ThisItem.IsLocked,
    "This phase is complete, so it cannot be changed.",
    "Select to change."
)
// STATE FIRST, ACTION ONLY IF THERE IS ONE. The worker name is
// gone from here because the row already announces it, and
// repeating it makes every control in the row read back the
// same name before saying anything useful.

If(
    ThisItem.Required,
    "Required. The phase waits for this worker.",
    "Not required. The phase does not wait for this worker."
)
& If(
    ThisItem.IsLocked,
    "  This phase is complete, so it cannot be changed.",
    If(
        ThisItem.Required,
        "  Select to make them optional.",
        "  Select to make them required."
    )
)
// INFORMATION FIRST. The old text opened with an instruction to
// select a control that is Disabled on every worker in a
// Completed phase, which is most of what anyone reading an
// existing workflow sees. What Required MEANS is the part that
// is always true and always useful; the instruction is
// conditional and comes second.
//
// The state has to be spoken because neither the border nor the
// glyph is announced, and the label is deliberately static.

If(
    ThisItem.Required,
    ButtonAppearance.Secondary,
    ButtonAppearance.Subtle
)
// THE STATE IS CARRIED THREE WAYS: the glyph, the weight and
// the presence of a border. Subtle draws no border at all, so
// ticked reads as a raised control and unticked reads as flat
// even on a screen where the icon font has not resolved. The
// previous version put the whole burden on the glyph, and if
// the icon name is wrong the two states become identical.

Patch(
    colWfDraftWorkers,
    LookUp(colWfDraftWorkers, ClientId = ThisItem.RowClientId),
    { Required: !ThisItem.Required }
);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)

Patch(
    colWfDraftWorkers,
    LookUp(colWfDraftWorkers, ClientId = ThisItem.RowClientId),
    { DurationDays: Max(ThisItem.DurationDays - 1, 1) }
);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)

Patch(
    colWfDraftWorkers,
    LookUp(colWfDraftWorkers, ClientId = ThisItem.RowClientId),
    { DurationDays: Min(ThisItem.DurationDays + 1, 60) }
);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)

Set(_cmpAwEditId, ThisItem.RowClientId);
Set(_cmpAwPhaseClientId, ThisItem.PhaseClientId);
Set(_cmpAwIsGroup, ThisItem.IsGroup);
Set(_cmpAwName, ThisItem.Title);
Set(_cmpAwId, If(ThisItem.IsGroup, ThisItem.GroupId, ThisItem.AssigneeEmail));
Set(_cmpAwGoal, ThisItem.Subtitle);
Set(_cmpAwDept, ThisItem.DepartmentCode);
Set(_cmpAwOrder, ThisItem.AssignmentOrder);
Set(_cmpAwDays, ThisItem.DurationDays);
Set(_cmpAwRequired, ThisItem.Required);
Set(_cmpAwOpen, true);
Reset(cmbAwPerson)

Patch(
    colWfDraftWorkers,
    LookUp(colWfDraftWorkers, ClientId = ThisItem.RowClientId),
    { IsRemoved: true }
);
Set(_cmpWfDirty, true);
Select(btnWfRebuild)

Set(_cmpAwEditId, 0);
Set(_cmpAwPhaseClientId, ThisItem.PhaseClientId);
Set(_cmpAwIsGroup, false);
Set(_cmpAwName, "");
Set(_cmpAwId, "");
Set(_cmpAwGoal, "");
Set(_cmpAwDept, "OPS");
Set(
    _cmpAwOrder,
    Last(
        Sort(
            Filter(colWfDraftWorkers, PhaseClientId = ThisItem.PhaseClientId, !IsRemoved),
            AssignmentOrder
        )
    ).AssignmentOrder + 1
);
// IDENTICAL TO THE PHASE ROW ADD BUTTON, DELIBERATELY. See the
// note there for the reasoning and for why it cannot be shared.
// If you change one, change both, and diff them afterwards.
Set(_cmpAwDays, 3);
Set(_cmpAwRequired, true);
